"""Genetics (tier 0.5j).

Edit freely — see data/__init__.py for how files are loaded."""


_GENETICS = {
    'autosomal dominant': "Autosomal Dominant — one mutant allele sufficient; vertical transmission; male = female affected; father-to-son transmission possible; examples: Huntington's (CAG repeat), Marfan (FBN1), ADPKD (PKD1/2), NF1, BRCA1/2, Li-Fraumeni (TP53), familial hypercholesterolemia (LDLR), achondroplasia (FGFR3 gain-of-function); penetrance and expressivity may vary",
    'autosomal recessive': "Autosomal Recessive — two mutant alleles required; horizontal transmission (siblings affected, parents carriers); consanguinity increases risk; equal sex distribution; examples: CF (CFTR), PKU (PAH), sickle cell (HBB), Tay-Sachs (HEXA), Gaucher (GBA), Wilson's (ATP7B), hemochromatosis (HFE), spinal muscular atrophy (SMN1)",
    'x-linked recessive': 'X-Linked Recessive — males affected (hemizygous); females are carriers (may show mild features); NO father-to-son transmission; examples: Duchenne/Becker MD (dystrophin), hemophilia A (F8) and B (F9), G6PD deficiency, X-linked agammaglobulinemia (BTK), Wiskott-Aldrich (WASP), color blindness, Fabry disease (GLA)',
    'x-linked dominant': 'X-Linked Dominant — both males and females affected; males often more severely affected (or lethal in males); no father-to-son; examples: Rett syndrome (MECP2), incontinentia pigmenti (IKBKG, lethal in males), hypophosphatemic rickets (PHEX), Alport syndrome (COL4A5 X-linked form)',
    'mitochondrial inheritance': 'Mitochondrial Inheritance — maternal inheritance (all children of affected mother at risk; children of affected father unaffected); mitochondrial DNA from egg only; heteroplasmy (mix of normal/mutant mtDNA → variable expression); examples: MELAS, MERRF, Leber hereditary optic neuropathy (LHON), Kearns-Sayre syndrome',
    'anticipation': "Anticipation — earlier onset and/or increased severity in successive generations due to expanding trinucleotide repeats; examples: Huntington's (CAG, paternal expansion), myotonic dystrophy (CTG, maternal expansion), Fragile X (CGG, maternal expansion), Friedreich's ataxia (GAA, no anticipation in classic sense); repeat length correlates with disease severity",
    'trinucleotide repeat': "Trinucleotide Repeat Disorders — dynamic mutations that expand with transmission; normal vs premutation vs full mutation; ANTICIPATION; key examples: Huntington's (CAG >36, chromosome 4), Fragile X (CGG >200, FMR1), Myotonic dystrophy type 1 (CTG, DMPK), Friedreich's ataxia (GAA, FXN — AR, no anticipation), SBMA/Kennedy (CAG, AR gene)",
    'genomic imprinting': "Genomic Imprinting — epigenetic silencing of one parental allele; only one allele expressed depending on parent of origin; Prader-Willi syndrome: deletion of paternal 15q11-q13 OR maternal UPD 15 (PWS: obese, hypotonia, hypogonadism); Angelman syndrome: deletion of maternal 15q11-q13 OR paternal UPD 15 (AS: 'happy puppet', seizures, absent speech, ataxia); KCNQ1OT1 (Beckwith-Wiedemann, paternal) vs H19 (maternal)",
    'uniparental disomy': 'Uniparental Disomy (UPD) — both copies of a chromosome pair from ONE parent; UPD of imprinted region → disease (Prader-Willi from maternal UPD 15; Angelman from paternal UPD 15); UPD can also cause AR disease if one chromosome is from a carrier parent (isodisomy); UPD of non-imprinted regions usually no phenotype',
    'incomplete penetrance': 'Incomplete Penetrance — not all individuals with disease genotype express the phenotype; penetrance = % of genotype carriers who show phenotype; examples: BRCA1/2 (penetrance <100% for breast cancer), hereditary pancreatitis (PRSS1), PALB2; contrast with expressivity (how severely phenotype is expressed)',
    'variable expressivity': 'Variable Expressivity — same genotype causes different phenotype severity among individuals; examples: NF1 (café-au-lait to malignant nerve sheath tumor), Marfan (mild to severe aortic disease), BRCA1 (breast vs ovarian cancer); caused by modifier genes, environment, stochastic factors',
    'mosaicism': 'Mosaicism — two or more genetically distinct cell populations in one individual; somatic mosaicism: post-zygotic mutation (e.g., McCune-Albright, GNAS; segmental NF1); germline mosaicism: mutation in gonadal cells only → recurrence risk in offspring despite unaffected parents; Pallister-Killian (tetrasomy 12p) often mosaic',
    'two hit hypothesis': 'Two-Hit Hypothesis (Knudson) — tumor suppressor genes require BOTH alleles to be inactivated; hereditary cancer: one mutation inherited (germline) + one somatic hit → earlier onset, multifocal; sporadic cancer: both somatic hits → later onset, unifocal; classic example: retinoblastoma (RB1); also: BRCA1/2, APC (FAP), VHL, NF1, NF2, WT1 (Wilms)',
    'loss of heterozygosity': "Loss of Heterozygosity (LOH) — loss of the remaining wild-type allele of a tumor suppressor gene; mechanism for '2nd hit' in Knudson model; detected by microsatellite analysis or SNP arrays; triggers tumor development in hereditary cancer syndromes; common at RB1, TP53, APC, BRCA1/2, VHL loci",
    'missense mutation': 'Missense Mutation — single nucleotide substitution → different amino acid; may be conservative (similar properties, e.g., Leu→Ile) or non-conservative (different properties, e.g., Val→Glu in sickle cell HbS); may or may not affect protein function; most common type of disease-causing point mutation',
    'nonsense mutation': 'Nonsense Mutation — point mutation creating a premature stop codon (UAA, UAG, UGA); truncated, usually non-functional protein; often leads to nonsense-mediated mRNA decay (NMD); examples: Duchenne MD (dystrophin), many tumor suppressors; readthrough therapy (ataluren) for some nonsense mutations',
    'frameshift mutation': 'Frameshift Mutation — insertion or deletion NOT in multiples of 3 → disrupts reading frame → completely altered downstream amino acid sequence + premature stop; usually severe loss-of-function; examples: Duchenne MD (out-of-frame deletions), BRCA1 (185delAG, 5382insC), Lynch syndrome (MMR gene insertions/deletions)',
    'splice site mutation': 'Splice Site Mutation — mutation at intron-exon boundary (GT-AG rule); may cause exon skipping, intron retention, or use of cryptic splice site; alters protein structure; exon-skipping drugs (eteplirsen) restore the reading frame in Duchenne MD, giving a shorter Becker-like dystrophin; splice site mutations in BRCA1/2, CLN3, IKBKAP (familial dysautonomia)',
    'fragile x syndrome': 'Fragile X Syndrome — FMR1 gene CGG repeat expansion (>200 = full mutation); X-linked, most common inherited intellectual disability; males: moderate-severe ID, macroorchidism, large ears, long face, hyperextensible joints; females: milder (50% show some features); premutation (55-200 repeats): fragile X-associated tremor/ataxia (FXTAS) in males; Sherman paradox (carrier males transmit expanded allele)',
    'prader-willi syndrome': 'Prader-Willi Syndrome — loss of paternal 15q11-q13 (70% deletion, 25% maternal UPD 15, 5% imprinting center defect); HHOHSS: Hypotonia + Hypogonadism + Obesity + Hyperphagia + Short stature + Skin picking/behavioral issues; almond-shaped eyes, small hands/feet; GH deficiency; treat with GH, strict dietary management',
    'angelman syndrome': "Angelman Syndrome — loss of maternal UBE3A expression (15q11-q13; 70% deletion, 5% paternal UPD 15, 5% UBE3A mutation); 'happy puppet' syndrome: severe ID, absent/minimal speech, seizures (EEG: high-amplitude delta waves), ataxia/tremulous movement, frequent laughter/smiling; microcephaly develops; fair coloring",
    'turner syndrome': 'Turner Syndrome — 45,X (or mosaicism 45X/46XX); female phenotype; gonadal dysgenesis (streak ovaries → primary amenorrhea, infertility); short stature, webbed neck (cystic hygroma remnant), shield chest, bicuspid aortic valve (MCC cardiac lesion), coarctation of aorta, horseshoe kidney; ↑FSH/LH (hypergonadotropic hypogonadism); normal intelligence; tx: estrogen replacement, GH',
    'klinefelter syndrome': 'Klinefelter Syndrome — 47,XXY (most common sex chromosome aneuploidy); male; tall stature, small firm testes, gynecomastia, azoospermia/infertility; mild learning difficulties (language); ↑FSH/LH, ↓testosterone; ↑risk: breast cancer, mediastinal germ cell tumor (extragonadal), SLE; tx: testosterone replacement; IVF-ICSI may achieve paternity',
    'down syndrome': "Down Syndrome (Trisomy 21) — MCC chromosomal aneuploidy in liveborns; features: intellectual disability, flat facies, upslanting palpebral fissures, epicanthal folds, single palmar crease, brushfield spots, hypotonia, atlantoaxial instability; cardiac (AVSD most common = 40%), duodenal atresia, Hirschsprung; ↑risk: ALL, Alzheimer's (APP on 21q); maternal age risk; dx prenatal: ↓AFP/estriol, ↑hCG/inhibin A",
    'brca1': 'BRCA1 (17q21) — tumor suppressor; DNA damage repair (homologous recombination); autosomal dominant; breast cancer lifetime risk ~70%, ovarian cancer ~44%, pancreatic ↑; triple-negative breast cancer common; Ashkenazi Jewish founder mutations (185delAG, 5382insC); PARP inhibitor synthetic lethality; risk reduction: bilateral mastectomy, salpingo-oophorectomy',
    'brca2': 'BRCA2 (13q12) — tumor suppressor; homologous recombination; breast cancer lifetime risk ~70%, ovarian ~17%, also: male breast cancer, pancreatic cancer, prostate cancer, melanoma; Fanconi anemia complementation group D1 (biallelic mutations); PARP inhibitor sensitivity; Ashkenazi founder: 6174delT',
    'li-fraumeni syndrome': 'Li-Fraumeni Syndrome — TP53 germline mutation (autosomal dominant); SBLA tumors: Sarcoma (soft tissue/bone) + Breast cancer (young onset) + brain tumors (glioblastoma, choroid plexus) + Leukemia + Lung/Laryngeal + Adrenocortical carcinoma; ↑risk for multiple primary cancers; whole-body MRI surveillance; avoid radiation therapy if possible',
    'lynch syndrome': 'Lynch Syndrome (HNPCC) — mismatch repair (MMR) gene mutations: MLH1 (most common), MSH2, MSH6, PMS2; autosomal dominant; colorectal cancer (right-sided, MSI-high) + endometrial (MCC extracolonic) + ovarian + gastric + urinary tract + small bowel; Amsterdam II criteria; IHC + microsatellite instability testing on tumor; universal CRC MMR testing; annual colonoscopy from age 20-25',
    'g6pd deficiency': 'G6PD Deficiency — X-linked recessive; oxidative stress → hemolytic anemia; triggers: primaquine, dapsone, nitrofurantoin, fava beans, infection, moth balls (naphthalene); Heinz bodies + bite cells on smear; ↑LDH, ↓haptoglobin; protective against malaria (most common enzymatic RBC disorder worldwide); dx: G6PD enzyme assay (wait until after hemolytic episode)',
    'achondroplasia': 'Achondroplasia — FGFR3 gain-of-function mutation (Gly380Arg); autosomal dominant; MCC short-limb dwarfism; rhizomelic (proximal > distal) limb shortening; macrocephaly, frontal bossing, midface hypoplasia, trident hand; normal intelligence; lumbar stenosis → neurological complications; 80% de novo mutations (↑paternal age); tx: vosoritide (CNP analog, recombinant, FDA approved)',
    'huntington disease': "Huntington's Disease — HTT gene CAG repeat >36 on chromosome 4p; autosomal dominant; anticipation (paternal expansion); onset usually 30-50 years (juvenile <20 if >60 repeats); chorea, cognitive decline (subcortical dementia), psychiatric symptoms (depression, psychosis); caudate atrophy (box-car ventricles on MRI); NO disease-modifying tx; tetrabenazine/deutetrabenazine for chorea; CAG length inversely correlates with age of onset",
    'cystic fibrosis': 'Cystic Fibrosis — CFTR gene (chromosome 7q31); autosomal recessive; ΔF508 deletion most common (70% of alleles); defective Cl⁻ channel → thick secretions; lungs: chronic bronchiectasis, Pseudomonas colonization; pancreas: exocrine insufficiency (malabsorption, steatorrhea), CF-related diabetes; vas deferens agenesis (male infertility); meconium ileus in neonates; sweat chloride >60 mEq/L diagnostic; tx: CFTR modulators (ivacaftor/elexacaftor-tezacaftor-ivacaftor for ΔF508)',
    'phenylketonuria': 'Phenylketonuria (PKU) — PAH gene mutation → phenylalanine hydroxylase deficiency; autosomal recessive; ↑phenylalanine → intellectual disability, seizures, hypopigmentation, musty odor (phenylacetic acid), eczema; newborn screening (Guthrie test); tx: phenylalanine-restricted diet + sapropterin (tetrahydrobiopterin, BH4 — for responsive variants); maternal PKU: low-phe diet during pregnancy essential',

    'tay-sachs disease': "Tay-Sachs Disease — AR; deficiency of hexosaminidase A (HEXA gene); accumulation of GM2 ganglioside in neurons; Ashkenazi Jewish, French-Canadian, Cajun populations (carrier freq 1/30); infantile (MCC): normal first 3-6 months → progressive motor/cognitive decline → cherry-red spot (macula) + NO hepatosplenomegaly (distinguishes from Niemann-Pick); startle response to sound; blindness; death by age 4-5; juvenile and adult forms exist",
    'gaucher disease': "Gaucher Disease — AR; MCC lysosomal storage disease; deficiency of glucocerebrosidase (GBA gene); accumulation of glucocerebroside in macrophages (Gaucher cells — 'crinkled paper' cytoplasm); Type 1 (nonneuronopathic, most common, Ashkenazi Jewish): hepatosplenomegaly + pancytopenia (bone marrow infiltration) + bone pain/AVN — NO CNS; Type 2 (acute neuronopathic): CNS + hepatosplenomegaly, fatal by age 2; Type 3: chronic neuronopathic; treatment: enzyme replacement therapy (imiglucerase) for Type 1; substrate reduction therapy (eliglustat)",
    'niemann-pick disease': "Niemann-Pick Disease — AR; two main types: Type A/B: sphingomyelinase deficiency → sphingomyelin accumulation; Type A: infants, Ashkenazi Jewish, progressive neurodegeneration + hepatosplenomegaly + cherry-red spot; Type B: visceral only, no CNS, survive to adulthood; Type C: NPC1/NPC2 gene mutation → impaired cholesterol trafficking; vertical gaze palsy (pathognomonic) + hepatosplenomegaly + ataxia + dementia; sea-blue histiocytes; foam cells in bone marrow",
    'factor v leiden': "Factor V Leiden Mutation — autosomal dominant with incomplete penetrance (heterozygotes 5-10x ↑DVT risk); missense mutation in Factor V gene (R506Q) → resistance to cleavage by Activated Protein C (APC resistance); MCC inherited thrombophilia in Europeans (5% carrier frequency); ↑risk DVT, PE; heterozygotes: 5-10x risk; homozygotes: 50-100x risk; testing: APC resistance assay + genetic confirmation; management: VTE episode → anticoagulation; asymptomatic carriers → thromboprophylaxis in high-risk situations",
    'prothrombin gene mutation': "Prothrombin G20210A Mutation — autosomal dominant (incomplete penetrance); point mutation in prothrombin (factor II) gene 3' UTR → elevated prothrombin levels (~150% normal); second MCC inherited thrombophilia in Europeans (~2-3% frequency); heterozygotes: 2-5x ↑VTE risk; homozygotes: rare, higher risk; often coexists with Factor V Leiden (compound heterozygotes: very high risk); diagnosis: PCR (genetic testing); management: same as Factor V Leiden",
    'hla associations': "HLA Associations — key HLA alleles and their associated diseases: HLA-B27: ankylosing spondylitis, reactive arthritis, psoriatic arthritis, IBD-associated arthritis (PAIR pneumonic); HLA-DR3/DR4: Type 1 diabetes (DR3+DR4 highest risk); HLA-DR3: SLE, Graves, Sjögren; HLA-DR4: RA, Type 1 DM; HLA-DQ2/DQ8: celiac disease (>95% of patients); HLA-B57:01: abacavir hypersensitivity (must screen before prescribing); HLA-B58:01: allopurinol SJS/TEN (screen in Han Chinese); HLA-B15:02: carbamazepine SJS (screen in Asian populations)",
    'mthfr mutation': "MTHFR C677T/A1298C — common polymorphism in methylenetetrahydrofolate reductase; ↑homocysteine (hyperhomocysteinemia); homozygous C677T (thermolabile variant): ↑↑ homocysteine + ↓folate; mild ↑VTE risk (controversial), ↑neural tube defect risk, cardiovascular risk; management: folate supplementation; many experts consider isolated MTHFR polymorphism without elevated homocysteine clinically insignificant; routine testing not recommended by ACMG",
    'hereditary hemochromatosis': "Hereditary Hemochromatosis — AR; MCC: HFE gene mutations (C282Y homozygote in 85% of cases, H63D compound heterozygote); C282Y: Northern European descent; ↓hepcidin → ↑ferroportin activity → ↑iron absorption → iron overload in parenchymal cells; classic triad: cirrhosis + diabetes mellitus + bronze skin ('bronze diabetes'); also: dilated cardiomyopathy, hypogonadism, arthropathy (2nd-3rd MCP joints — chondrocalcinosis), hepatocellular carcinoma; labs: ↑ferritin + ↑transferrin saturation (>45%); diagnosis: HFE genotyping; liver biopsy (hepatic iron index); treatment: phlebotomy weekly until ferritin <50 → maintenance q2-4 months; chelation (deferoxamine) if phlebotomy not possible",
    'retinoblastoma genetics': "Retinoblastoma — two-hit hypothesis (Knudson): both alleles of RB1 (tumor suppressor, chr 13q14) must be inactivated; sporadic (60%): both mutations somatic, unilateral, older age; hereditary (40%): germline mutation (1st hit) + somatic mutation (2nd hit), bilateral, earlier age, AD inheritance; germline RB1 → ↑risk osteosarcoma and other cancers (pinealoblastoma — 'trilateral retinoblastoma'); pRb: controls G1→S checkpoint by binding E2F transcription factors",
    'cftr mutations': "CFTR Mutations — cystic fibrosis (AR); >2000 CFTR mutations; classes by molecular mechanism: Class I (nonsense — no protein, e.g., G542X); Class II (misfolding/degradation — most common, ΔF508/F508del — 70% of CF alleles, retained in ER); Class III (gating defect — reaches membrane but doesn't open, G551D); Class IV (conductance — reduced Cl- flow); Class V (splicing — reduced protein); Class VI (instability); treatment by class: Class II+III: elexacaftor/tezacaftor/ivacaftor (Trikafta — restores ΔF508 trafficking + G551D gating); Class III alone: ivacaftor",
    'robertsonian translocation': 'Robertsonian Translocation — fusion of the long arms of two acrocentric chromosomes (13, 14, 15, 21, 22) at the centromere, losing the short arms (no clinical effect — their rRNA genes are repeated elsewhere); carriers have 45 chromosomes and are healthy but risk unbalanced offspring; t(14;21) causes ~4% of Down syndrome (translocation Down — higher recurrence risk, test the parents); the most common chromosomal rearrangement (~1 in 1000)',
    'reciprocal translocation': 'Reciprocal Translocation — exchange of segments between two non-homologous chromosomes; balanced carriers are usually healthy but have recurrent miscarriage or unbalanced offspring; acquired translocations drive cancers: t(9;22) BCR-ABL (CML, Ph+ ALL), t(8;14) MYC-IGH (Burkitt), t(14;18) BCL2-IGH (follicular lymphoma), t(11;14) CCND1-IGH (mantle cell), t(15;17) PML-RARA (APL — treat with ATRA)',
    'nondisjunction': 'Nondisjunction — failure of homologous chromosomes (meiosis I) or sister chromatids (meiosis II) to separate → gametes with an extra or missing chromosome → trisomy or monosomy; most common cause of aneuploidy (95% of Down syndrome, Edwards, Patau, Klinefelter, Turner); risk rises with maternal age (mostly maternal meiosis I errors); nondisjunction after fertilization (mitotic) causes mosaicism',
    'heteroplasmy': "Heteroplasmy — a cell or tissue contains both normal and mutant mitochondrial DNA; severity depends on the mutant fraction and the tissue's energy demand (threshold effect — brain, muscle, retina most affected); explains variable expression within families with mitochondrial disease (MELAS, MERRF, LHON)",
    'locus heterogeneity': 'Locus Heterogeneity — mutations in DIFFERENT genes produce the same phenotype; examples: albinism, retinitis pigmentosa, hereditary hearing loss, familial hypercholesterolemia (LDLR, APOB, PCSK9), tuberous sclerosis (TSC1 or TSC2); contrast allelic heterogeneity (different mutations in the SAME gene)',
    'allelic heterogeneity': 'Allelic Heterogeneity — different mutations in the SAME gene cause the same or a similar disease; examples: β-thalassemia (hundreds of HBB mutations with varying severity), cystic fibrosis (>2000 CFTR variants, F508del most common), Duchenne vs Becker (frameshift vs in-frame dystrophin deletions); contrast locus heterogeneity (different genes → same phenotype)',
    'pleiotropy': 'Pleiotropy — one gene mutation causes multiple, seemingly unrelated effects in different organ systems; examples: PKU (intellectual disability, fair skin, musty odor, eczema), Marfan (FBN1 — tall stature, lens dislocation, aortic root dilation), cystic fibrosis (lungs, pancreas, sweat glands, vas deferens), osteogenesis imperfecta (fractures, blue sclerae, hearing loss)',
    'hardy-weinberg': 'Hardy-Weinberg Principle — in a large, randomly mating population without mutation, selection or migration: p + q = 1 and p² + 2pq + q² = 1 (p² = homozygous dominant, 2pq = heterozygous carriers, q² = affected homozygous recessive); for a rare AR disease, carrier frequency ≈ 2q = 2√(prevalence); X-linked recessive: male prevalence = q, female = q²; example: CF 1/2500 → q = 1/50 → carriers ≈ 1/25',
    'de novo mutation': 'De Novo Mutation — a new mutation present in the child but not in either parent (arises in a parental gamete or the early embryo); common in achondroplasia (~80%, linked to advanced paternal age), NF1 (~50%), Duchenne MD (~1/3), Rett syndrome, osteogenesis imperfecta; recurrence risk is low but not zero (germline mosaicism in a parent)',
    'duchenne muscular dystrophy': 'Duchenne Muscular Dystrophy — X-linked recessive; frameshift/nonsense mutation (usually a deletion) in DMD (dystrophin — the largest human gene, Xp21) → absent dystrophin; boys aged 2-5: proximal weakness, Gowers sign, calf pseudohypertrophy (fibrofatty replacement), waddling gait, very high CK; wheelchair by ~12; death from dilated cardiomyopathy or respiratory failure; ~1/3 de novo; corticosteroids (deflazacort), exon-skipping drugs; Becker = in-frame deletion → partly functional dystrophin, milder and later',
    'myotonic dystrophy': "Myotonic Dystrophy Type 1 — AD; CTG repeat expansion in DMPK (chromosome 19) with anticipation (maternal transmission → congenital form); myotonia (cannot release a grip), distal and facial weakness ('hatchet face'), frontal balding, early cataracts, testicular atrophy, insulin resistance, cardiac conduction defects (sudden death — annual ECG)",
    'friedreich ataxia': 'Friedreich Ataxia — AR; GAA repeat expansion in FXN (frataxin — mitochondrial iron handling, chromosome 9) → loss of function; onset in childhood/adolescence: progressive gait and limb ataxia, dysarthria, absent ankle reflexes with up-going plantars, loss of proprioception/vibration (dorsal columns), pes cavus, kyphoscoliosis; hypertrophic cardiomyopathy (main cause of death) and diabetes; omaveloxolone approved 2023',
    'edwards syndrome': 'Edwards Syndrome (Trisomy 18) — nondisjunction; second most common autosomal trisomy at birth; severe intellectual disability, rocker-bottom feet, clenched fists with overlapping fingers, micrognathia, low-set ears, prominent occiput, congenital heart disease (VSD), horseshoe kidney; most die within the first year; quad screen: ↓AFP, ↓hCG, ↓estriol, normal/↓inhibin A',
    'patau syndrome': 'Patau Syndrome (Trisomy 13) — nondisjunction; holoprosencephaly, microphthalmia, cleft lip/palate, polydactyly, cutis aplasia (scalp defects), rocker-bottom feet, congenital heart disease, polycystic kidneys, omphalocele; severe intellectual disability; most die within the first year; first-trimester screen: ↓PAPP-A, ↓free β-hCG',
    'cri du chat syndrome': 'Cri-du-Chat Syndrome — deletion of the short arm of chromosome 5 (5p−); high-pitched cat-like cry in infancy, microcephaly, moderate-severe intellectual disability, hypertelorism, epicanthal folds, cardiac defects (VSD)',
    'x-inactivation': 'X-Inactivation (Lyonization) — in each female cell one X chromosome is randomly silenced early in development (XIST RNA → Barr body), so females are mosaics for X-linked genes; skewed inactivation explains symptomatic carrier females (e.g. hemophilia or DMD carriers); Barr bodies = number of X chromosomes − 1 (Klinefelter 47,XXY has one)',
}
